import sys

def main():
    data = sys.stdin.read().split()
    M, N, q = int(data[0]), int(data[1]), int(data[2])
    cnt = [0] * (M * N)
    parent = list(range(M * N))

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    zones = 0
    pos = 3
    out = []
    for _ in range(q):
        op = data[pos]
        pos += 1
        if op == 'zones':
            out.append(str(zones))
            continue
        r, c = int(data[pos]), int(data[pos + 1])
        pos += 2
        idx = r * N + c
        if op == 'open':
            cnt[idx] += 1
            if cnt[idx] == 1:
                zones += 1
                for a, b in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= a < M and 0 <= b < N and cnt[a * N + b] > 0:
                        x, y = find(idx), find(a * N + b)
                        if x != y:
                            parent[x] = y
                            zones -= 1
        elif op == 'count':
            out.append(str(cnt[idx]))
        else:
            out.append('true' if cnt[idx] > 0 else 'false')
    print('\n'.join(out))

main()

